mapper.sql:
WHERE c.tenant_id = #{tenantId} AND c.deleted = 0



    AND (c.owner_staff_id = #{selfId}

      OR c.team_id IN #{t}
    )


    AND c.owner_staff_id = #{selfId}

  AND 1 = 0


  AND c.owner_staff_id = #{ownerId}


  AND (c.customer_no LIKE CONCAT('%', #{keyword}, '%')
    OR c.display_name LIKE CONCAT('%', #{keyword}, '%')
    OR c.nickname LIKE CONCAT('%', #{keyword}, '%')
    OR c.remark_name LIKE CONCAT('%', #{keyword}, '%')

      OR c.mobile_hash = #{mobileHashKeyword}
    )


  AND c.customer_status = #{status}


  AND c.city_code = #{cityCode}


  AND c.source_code = #{sourceCode}


  AND c.channel_code = #{channelCode}


  AND c.tier_code = #{tierCode}


  AND EXISTS (SELECT 1 FROM crm_followup f
              WHERE f.tenant_id = c.tenant_id AND f.customer_id = c.id AND f.deleted = 0
                AND f.next_followup_at IS NOT NULL AND f.next_followup_at <= #{followupDueBefore})

